require __DIR__.'/app/bootstrap.php'; require __DIR__.'/app/layout.php'; $admin=require_permission('manage_users'); $id=(int)($_GET['id']??$_POST['id']??0);$q=db()->prepare('SELECT id,full_name,username FROM users WHERE id=?');$q->execute([$id]);$target=$q->fetch();if(!$target){http_response_code(404);exit('User not found.');}$temporary='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$temporary=strtoupper(bin2hex(random_bytes(5)));db()->prepare('UPDATE users SET password_hash=?,must_change_password=1 WHERE id=?')->execute([password_hash($temporary,PASSWORD_DEFAULT),$id]);}
page_start('Reset password',$admin);?><h1>Reset password</h1><p><?=e($target['full_name'])?> (<?=e($target['username'])?>)</p><?php if($temporary):?><p><strong>Save this temporary password now:</strong> <code><?=e($temporary)?></code></p><p>The user must change it at next login.</p><?php else:?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$id?>"><button class="button">Generate temporary password</button></form><?php endif;?><?php page_end();
